check:
{v:'VER',what:'cloud-coop-bounty-end-said: the end of a bounty pillager is said in player 2 window too, the exact line the host said: claimed by player 2 (and no pay of its own), not your kill, he got away, slipped away, over he stays, even when the pillager dies or leaves after the host spoke and before the word',
 run:function(){
   if(!(window.__state&&window.__endRaid&&window.__runPrep&&window.__topClear)) return 'SKIP: no raid here';
   if(typeof arcadeDeploy!=='function'||typeof ARCADE!=='object'||typeof netWorldSend!=='function'||typeof netOnMsg!=='function'||typeof evLaunch!=='function'||typeof evTick!=='function'||typeof flowTick!=='function'||typeof BOUNTY!=='object') return 'SKIP: no arcade, party or events in this fixture';
   var bad=[], g=null, p=null, NK={}, k, oSF=netSendFast, oS=netSend, oB=netBroadcast, oSay=say, sent=[], w=null, h={seat:0,state:'in'}, HF=null, PF={}, staged=false, i, oIv=null, side='host', L={host:[],p2:[]}, nid=950, r, skip=null;
   function word(){ var q; for(q=sent.length-1;q>=0;q--) if(sent[q].t==='wd') return sent[q]; return null; }
   function asHost(){ side='host'; NET.role='host'; NET.seat=0; NET.peers=[{seat:1,state:'in'}]; NET.upSeed=g.seed>>>0; g.flow=HF; }
   function asTwo(){ side='p2'; NET.role='join'; NET.seat=1; NET.peers=[h]; NET.upSeed=g.seed>>>0; g.flow=PF; }
   function sendTake(){ sent.length=0; asHost(); netWorldSend(); w=word(); asTwo(); if(w) netOnMsg(h,JSON.stringify(w)); sent.length=0; asHost(); return w; }
   function ends(a){ return a.filter(function(q){ return (/^BOUNTY /).test(q)&&!(/^BOUNTY ON THE MAP\|/).test(q); }); }
   function one(name,want,act,race){
     var ev, e, hl, pl, m0, m1, j;
     asHost(); HF.ev.live=[]; sendTake();
     ev=evLaunch('bounty'); if(!ev){ skip='SKIP: '+name+': the host launched no bounty'; return; }
     ev.t=ev.warn; evTick(0.01);
     if(ev.ph!=='live'||!ev.d.e){ skip='SKIP: staging: '+name+': the bounty did not go live'; return; }
     e=ev.d.e; nid++; e.nid=nid; NET.entMap[nid]=e;
     sendTake();
     if(!PF.ev||!PF.ev.live||!PF.ev.live.length||PF.ev.live[0].ph!=='live'){ bad.push(name+': player 2 window did not take the live bounty'); return; }
     L={host:[],p2:[]};
     act(ev,e);
     for(j=0;j<10&&ev.ph==='live';j++){ g.t+=0.1; flowTick(0.1); }
     hl=ends(L.host);
     if(hl.length!==1||!(want).test(hl[0])){ skip='SKIP: staging: '+name+': the host said '+JSON.stringify(hl); return; }
     if(race) race(ev,e);
     m0=ARCADE.mine|0; sendTake(); sendTake(); sendTake(); m1=ARCADE.mine|0;
     pl=ends(L.p2);
     if(pl.length!==1||pl[0]!==hl[0]) bad.push(name+': the host said '+hl[0]+', player 2 window said '+JSON.stringify(pl));
     if(m1!==m0) bad.push(name+': taking the end moved the money in player 2 window ('+m0+' to '+m1+')');
   }
   function far(e){ e.seen=0; e.x=(p.x>2400)?p.x-2000:p.x+2000; e.y=p.y; }
   try{
     __topClear(); __runPrep();
     if(ARCADE.on) return 'SKIP: the arcade is on after __topClear';
     if(!arcadeDeploy({mapIx:0,seed:4242})) return 'SKIP: arcadeDeploy built no arcade raid';
     g=__state(); if(!g||g.over||!g.player) return 'SKIP: no live raid';
     p=g.player; oIv=p.iv; p.iv=99;
     for(k in NET) NK[k]=NET[k]; staged=true;
     NET.on=true; NET.max=4; NET.specG=null; NET.up=[]; NET.entMap={};
     netSendFast=function(q,m){ sent.push(JSON.parse(JSON.stringify(m))); return true; };
     netSend=function(q,m){ sent.push(JSON.parse(JSON.stringify(m))); return true; };
     netBroadcast=function(m){ sent.push(JSON.parse(JSON.stringify(m))); return 1; };
     say=function(a,b,c){ L[side].push(String(a)+'|'+((c&&c.sub)||'')+'|'+String(b||'')); };
     HF=g.flow||{}; HF.ev={plan:[],live:[],n:0,wrecks:[]}; HF.sh={sites:[]}; HF.fplan=[];
     asHost(); g.t=60;
     one('player 2 kill',/^BOUNTY CLAIMED\|BOUNTY PILLAGER/,function(ev,e){ e.hp=0; e.byPlayer=false; e.bySeat=1; });
     one('claimed then gone before the word',/^BOUNTY CLAIMED\|/,function(ev,e){ e.hp=0; e.byPlayer=false; e.bySeat=1; },function(ev,e){ r=g.ents.indexOf(e); if(r>=0) g.ents.splice(r,1); });
     one('not your kill',/^BOUNTY GONE\|NOT YOUR KILL/,function(ev,e){ e.hp=0; e.byPlayer=false; e.bySeat=0; });
     one('he got away',/^BOUNTY GONE\|HE GOT AWAY/,function(ev,e){ r=g.ents.indexOf(e); if(r>=0) g.ents.splice(r,1); });
     one('slipped away',/^BOUNTY SLIPPED AWAY\|/,function(ev,e){ far(e); ev.lt=ev.dur-0.05; });
     one('he stays',/^BOUNTY OVER\|HE STAYS/,function(ev,e){ e.seen=1; ev.lt=ev.dur-0.05; });
     one('he stays then dies before the word',/^BOUNTY OVER\|HE STAYS/,function(ev,e){ e.seen=1; ev.lt=ev.dur-0.05; },function(ev,e){ e.hp=0; e.bySeat=1; r=g.ents.indexOf(e); if(r>=0) g.ents.splice(r,1); });
     if(bad.length) return bad.join(' / ');
     return skip;
   }catch(e){ return 'threw: '+(e&&e.message||e); }
   finally{
     netSendFast=oSF; netSend=oS; netBroadcast=oB; say=oSay;
     if(staged){ for(k in NET) if(!(k in NK)) delete NET[k]; for(k in NK) NET[k]=NK[k]; }
     try{ if(g&&HF) g.flow=HF; }catch(_g){}
     if(p&&oIv!==null) p.iv=oIv;
     try{ if(typeof ARCADE==='object'&&ARCADE.on) arcadeLeave(); }catch(_l){}
     try{ if(__state()&&!__state().over) __endRaid('abandon'); }catch(_e){}
     __topClear();
   }
 }},
